<?php $this->layout('default'); use Moves\Services\CmsSettings as S; use Moves\Support\CmsView as V; $groups = []; foreach (S::FIELDS as $k => [$g, $l, $t]) { $groups[$g][$k] = [$l, $t]; } ?>
<form method="post" action="/acao/settings-save"><?= V::csrf() ?><?php foreach ($groups as $g => $fields): ?><div class="cms-card"><h2><?= V::e($g) ?></h2><div class="cms-form-grid"><?php foreach ($fields as $k => [$l, $t]): ?><?= V::field($l, $k, S::get($k), ['type' => $t]) ?><?php endforeach; ?></div></div><?php endforeach; ?><p><button class="cms-btn-primary">Salvar configurações</button></p></form>
<div class="cms-alert cms-alert-info">Categorias, metas e canais de atendimento ficam em <a href="/chamados/notificacoes">Configurações de notificações</a>. Segredos permanecem no arquivo .env e não são editáveis aqui.</div>
